AND ( drug_code LIKE CONCAT('%', #{keyword}, '%') OR drug_name LIKE CONCAT('%', #{keyword}, '%') OR generic_name LIKE CONCAT('%', #{keyword}, '%') )
AND category = #{category}
AND enabled = #{enabled}
ORDER BY updated_at DESC, id DESC LIMIT #{pageSize} OFFSET #{offset}

